const input = $input.first().json || {};

let normalizedLead = input.normalized_lead || {};
let enrichment = input.enrichment || {};
let deduplication = input.deduplication || {};

if (typeof normalizedLead === "string") normalizedLead = JSON.parse(normalizedLead);
if (typeof enrichment === "string") enrichment = JSON.parse(enrichment);
if (typeof deduplication === "string") deduplication = JSON.parse(deduplication);

function clean(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

const eventId = Number(input.event_id || input.run_id);
const leadId = Number(input.lead_id);

if (!eventId || Number.isNaN(eventId)) {
  throw new Error("Missing valid event_id/run_id");
}

if (!leadId || Number.isNaN(leadId)) {
  throw new Error("Missing valid lead_id");
}

if (!enrichment || typeof enrichment !== "object") {
  throw new Error("Missing enrichment object from Workflow 03");
}

const scoringContext = {
  lead: {
    lead_id: leadId,
    lead_name: clean(input.lead_name),
    lead_email: clean(input.lead_email),
    lead_phone: clean(input.lead_phone),
    lead_source: clean(input.lead_source || input.event_source),
    job_title: clean(input.job_title),
    message: clean(input.message),
    budget: clean(input.budget),
    timeline: clean(input.timeline),
    country: clean(input.country)
  },

  company: {
    company_name: clean(input.company_name || enrichment.company?.company_name),
    company_domain: clean(input.company_domain || enrichment.company?.company_domain),
    website_url: clean(input.website_url || enrichment.company?.website_url),
    industry: clean(enrichment.company?.industry),
    company_size_estimate: clean(enrichment.company?.company_size_estimate),
    business_model: clean(enrichment.company?.business_model)
  },

  enrichment: {
    person: enrichment.person || {},
    company: enrichment.company || {},
    intent: enrichment.intent || {},
    routing_context: enrichment.routing_context || {},
    metadata: enrichment.metadata || {}
  },

  deduplication,

  source: {
    event_id: eventId,
    external_id: clean(input.external_id),
    event_source: clean(input.event_source)
  }
};

return [
  {
    json: {
      run_id: eventId,
      event_id: eventId,
      external_id: clean(input.external_id),
      event_source: clean(input.event_source) || "website_form",

      lead_id: leadId,
      lead_name: clean(input.lead_name),
      lead_email: clean(input.lead_email),
      lead_phone: clean(input.lead_phone),
      lead_source: clean(input.lead_source || input.event_source),

      company_name: clean(input.company_name || enrichment.company?.company_name),
      company_domain: clean(input.company_domain || enrichment.company?.company_domain),
      website_url: clean(input.website_url || enrichment.company?.website_url),

      job_title: clean(input.job_title || enrichment.person?.job_title),
      message: clean(input.message),
      budget: clean(input.budget || enrichment.intent?.budget_signal),
      timeline: clean(input.timeline || enrichment.intent?.timeline_signal),
      country: clean(input.country || enrichment.company?.country),

      normalized_lead: normalizedLead,
      deduplication,
      enrichment,

      scoring_context: scoringContext,
      scoring_context_json: JSON.stringify(scoringContext)
    }
  }
];

const data = $input.first().json;

const prompt = `
Score this inbound B2B lead for an AI automation / operations automation service.

Return ONLY valid raw JSON.
Do not use markdown.
Do not use code fences.
Do not explain outside JSON.

Scoring rules:
- lead_score must be an integer from 0 to 100.
- High fit: 75-100.
- Medium fit: 45-74.
- Low fit: 0-44.
- Prioritize leads with:
  - clear operational pain;
  - specific automation use case;
  - business urgency;
  - budget;
  - timeline;
  - decision-maker or strong operator role;
  - company context that matches B2B automation work.
- Penalize leads with:
  - missing contact data;
  - vague message;
  - unclear company;
  - no business problem;
  - student/research/vendor/spam intent;
  - no automation use case.
- Do not invent facts.
- Use missing_information for data needed before a sales call.

INPUT_JSON:
${data.scoring_context_json}

Return exactly this JSON schema:

{
  "lead_score": 0,
  "fit_level": "Low",
  "priority": "Low",
  "routing_team": "Sales",
  "lead_status": "qualified",
  "recommended_next_action": "",
  "reasoning_summary": "",
  "positive_signals": [],
  "negative_signals": [],
  "missing_information": [],
  "suggested_owner_role": "",
  "follow_up_angle": "",
  "qualification_notes": ""
}
`;

return [
  {
    json: {
      ...data,
      final_scoring_prompt: prompt
    }
  }
];

const raw =
  $json.output ||
  $json.text ||
  $json.content ||
  $json.message ||
  JSON.stringify($json);

const input = $('Build Scoring Prompt').first().json;

function cleanText(value) {
  if (!value) return "";
  return String(value).trim();
}

function normalizeArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  return [String(value).trim()].filter(Boolean);
}

function normalizeValue(value, allowed, fallback) {
  const clean = cleanText(value);
  return allowed.includes(clean) ? clean : fallback;
}

function parseJsonFromText(value) {
  let text = String(value || "").trim();

  text = text
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();

  const first = text.indexOf("{");
  const last = text.lastIndexOf("}");

  if (first !== -1 && last !== -1) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

const parsed = parseJsonFromText(raw);

let score = Number(parsed.lead_score);
if (Number.isNaN(score)) score = 0;
score = Math.max(0, Math.min(100, Math.round(score)));

let fitLevel;
if (score >= 75) {
  fitLevel = "High";
} else if (score >= 45) {
  fitLevel = "Medium";
} else {
  fitLevel = "Low";
}

const allowedPriorities = ["Low", "Medium", "High", "Urgent"];
const allowedRoutingTeams = ["Sales", "RevOps", "Automation Consulting", "Support", "Nurture"];
const allowedStatuses = ["qualified", "nurture", "disqualified"];

let defaultPriority = "Low";
if (score >= 85) defaultPriority = "Urgent";
else if (score >= 75) defaultPriority = "High";
else if (score >= 45) defaultPriority = "Medium";

let defaultStatus = "disqualified";
if (score >= 75) defaultStatus = "qualified";
else if (score >= 45) defaultStatus = "nurture";

const positiveSignals = normalizeArray(parsed.positive_signals);
const negativeSignals = normalizeArray(parsed.negative_signals);
const missingInformation = normalizeArray(parsed.missing_information);

const leadScore = {
  lead_score: score,
  fit_level: fitLevel,

  priority: normalizeValue(
    parsed.priority,
    allowedPriorities,
    defaultPriority
  ),

  routing_team: normalizeValue(
    parsed.routing_team,
    allowedRoutingTeams,
    fitLevel === "High" ? "Automation Consulting" : "Nurture"
  ),

  lead_status: normalizeValue(
    parsed.lead_status,
    allowedStatuses,
    defaultStatus
  ),

  recommended_next_action: cleanText(parsed.recommended_next_action),
  reasoning_summary: cleanText(parsed.reasoning_summary),

  positive_signals: positiveSignals,
  negative_signals: negativeSignals,
  missing_information: missingInformation,

  suggested_owner_role: cleanText(parsed.suggested_owner_role),
  follow_up_angle: cleanText(parsed.follow_up_angle),
  qualification_notes: cleanText(parsed.qualification_notes),

  scored_at: new Date().toISOString()
};

// Extra deterministic safety rules.
if (!input.lead_email && !input.lead_phone) {
  leadScore.lead_status = "nurture";
  leadScore.priority = leadScore.priority === "Urgent" ? "High" : leadScore.priority;
  leadScore.missing_information.push("Contact email or phone is missing.");
}

if (!input.message && leadScore.lead_score > 70) {
  leadScore.lead_score = 70;
  leadScore.fit_level = "Medium";
  leadScore.lead_status = "nurture";
  leadScore.missing_information.push("Lead message or business problem is missing.");
}

if (
  leadScore.negative_signals.some(signal =>
    signal.toLowerCase().includes("spam") ||
    signal.toLowerCase().includes("student") ||
    signal.toLowerCase().includes("vendor")
  )
) {
  leadScore.lead_score = Math.min(leadScore.lead_score, 30);
  leadScore.fit_level = "Low";
  leadScore.priority = "Low";
  leadScore.lead_status = "disqualified";
}

return [
  {
    json: {
      ...input,
      lead_score: leadScore
    }
  }
];

